class LibraryMember {private static int enrolled;private final int memberNumber;protected int borrowed;private java.util.List<String> genres=new java.util.ArrayList<>();public LibraryMember(int limit){if(limit<=0)throw new IllegalArgumentException();memberNumber=++enrolled;}public void borrowBook(){borrowed++;}public void borrowBook(String genre){genres.add(genre);borrowBook();}public int getBooksBorrowed(){return borrowed;}public static int getMembersEnrolled(){return enrolled;}public int getMemberNumber(){return memberNumber;}}
class FacultyMember extends LibraryMember {String department;public FacultyMember(int l,String d){super(l);department=d;}}
public class Problem5_MembershipNumbersRenewalAudit {static boolean isValidRenewalCode(String s){return s!=null&&s.length()==4&&s.charAt(0)=='R'&&Character.isDigit(s.charAt(1))&&Character.isDigit(s.charAt(2))&&Character.isUpperCase(s.charAt(3));}static String processNightlyAudit(LibraryMember[] ms){int p=0,n=0,f=0,r=0;for(LibraryMember m:ms){if(m==null){n++;continue;}p++;if(m instanceof FacultyMember)f++;else r++;}return p+" processed | "+n+" null skipped | "+f+" faculty | "+r+" regular";}public static void main(String[]x){LibraryMember m=new LibraryMember(3);m.borrowBook();m.borrowBook("Fiction");System.out.println(m.getBooksBorrowed());System.out.println(isValidRenewalCode("R12A"));System.out.println(processNightlyAudit(new LibraryMember[]{new FacultyMember(5,"Physics"),null,new LibraryMember(3)}));}}